import{_ as e,C as n,o as l,c as h,j as t,E as i,a as r,a2 as o}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"8-sinf (Web Full-stack)","link":"/mentor/8-sinf/"},"n":1,"bob":"I-bob · HTML tili va veb-sahifa tuzishning asoslari","lessons":[{"g":1,"title":"Internet qanday ishlaydi? DNS, hosting, domain. Front-end va Back-end","lead":"Telegramda xabar yozasiz, YouTube'da video ochasiz: bir soniyada hammasi ekranda. Bu darsda \\"parda ortiga\\" kirib, brauzer, DNS va server qanday hamkorlik qilishini ko'ramiz.","link":"/mentor/8-sinf/hafta-01/dars-1","slide":"/slaydlar/8-sinf/hafta-01/dars-1.html","test":"/slaydlar/8-sinf/hafta-01/dars-1-test.html"},{"g":2,"title":"HTML hujjat strukturasi. Teg, atribut, head, sarlavhalar","lead":"Bugun siz birinchi marta brauzer tushunadigan haqiqiy HTML faylni o'zingiz yozasiz: skelet, ko'rinmas sozlamalar va sarlavhalar. Shundan keyin istalgan sayt «ichini» ochib o'qiy olasiz.","link":"/mentor/8-sinf/hafta-01/dars-2","slide":"/slaydlar/8-sinf/hafta-01/dars-2.html","test":"/slaydlar/8-sinf/hafta-01/dars-2-test.html"},{"g":3,"title":"Matn teglari, <a> tegi, block va inline elementlar","lead":"Oddiy matn bugun «jonlanadi»: so'zlar qalin, qiyshiq, sariq bo'ladi va bosiladigan havolaga aylanadi. Telegramdagi har bir ko'k yozuv qanday ishlashini ham bilib olasiz.","link":"/mentor/8-sinf/hafta-01/dars-3","slide":"/slaydlar/8-sinf/hafta-01/dars-3.html","test":"/slaydlar/8-sinf/hafta-01/dars-3-test.html"}],"test":"/slaydlar/8-sinf/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/8-sinf/hafta-01/index.md","filePath":"mentor/8-sinf/hafta-01/index.md"}`),s={name:"mentor/8-sinf/hafta-01/index.md"},u={class:"blk"},c={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},m={id:"baholash-mezoni",tabindex:"-1"};function b(k,a,f,y,v,z){const d=n("Icon");return l(),h("div",null,[t("div",u,[t("h2",c,[i(d,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Har bir vazifa 20–30 daqiqa. Fayllar alohida <code>hafta-01</code> papkasida saqlanadi.</p><h2 id="_1-dars-uchun-internet-dns-hosting" tabindex="-1">1-dars uchun (Internet, DNS, hosting) <a class="header-anchor" href="#_1-dars-uchun-internet-dns-hosting" aria-label="Permalink to &quot;1-dars uchun (Internet, DNS, hosting)&quot;">​</a></h2><p><strong>1-topshiriq: «Mening internetim»</strong> (daftarda yoki matn faylida)</p><ol><li>O&#39;zingiz yoqtirgan 3 ta saytni yozing. Har birining domenini qismlarga ajrating (nom va zona, masalan <code>kun</code> + <code>.uz</code>).</li><li>Bitta saytni tanlab, sahifa ochilguncha bo&#39;ladigan bosqichlarni o&#39;z so&#39;zingiz bilan 5 ta gap bilan yozing (brauzer, DNS, server).</li><li>O&#39;sha saytdan front-end va back-end ga misollar yozing (2 tadan).</li></ol><p><strong>Kutiladigan natija:</strong> to&#39;g&#39;ri atamalar, o&#39;z so&#39;zi bilan yozilgan matn.</p><h2 id="_2-dars-uchun-html-skelet-head-sarlavhalar" tabindex="-1">2-dars uchun (HTML skelet, head, sarlavhalar) <a class="header-anchor" href="#_2-dars-uchun-html-skelet-head-sarlavhalar" aria-label="Permalink to &quot;2-dars uchun (HTML skelet, head, sarlavhalar)&quot;">​</a></h2><p><strong>2-topshiriq: «Sevimli o&#39;yinim/ hobbim» sahifasi</strong><code>hobbi.html</code>: to&#39;liq skelet (<code>lang=&quot;uz&quot;</code>, <code>charset</code>, <code>viewport</code>, <code>description</code>, <code>author</code>, <code>title</code>), <code>&lt;h1&gt;</code>, ikkita <code>&lt;h2&gt;</code>, ularning ostida abzatslar; bitta <code>&lt;h3&gt;</code>. <strong>Tekshirish:</strong> brauzerda ochiladi, yorliqda sarlavha bor, o&#39;zbekcha harflar to&#39;g&#39;ri, kodda surish (indent) bor, barcha teglar yopilgan.</p><h2 id="_3-dars-uchun-matn-teglari-havolalar" tabindex="-1">3-dars uchun (matn teglari, havolalar) <a class="header-anchor" href="#_3-dars-uchun-matn-teglari-havolalar" aria-label="Permalink to &quot;3-dars uchun (matn teglari, havolalar)&quot;">​</a></h2><p><strong>3-topshiriq: «Qiziqarli ma&#39;lumot»</strong><code>malumot.html</code>: 3 ta abzatsli kichik maqola. Maqolada kamida: <code>&lt;strong&gt;</code>, <code>&lt;em&gt;</code>, <code>&lt;mark&gt;</code>, <code>&lt;sub&gt;</code> yoki <code>&lt;sup&gt;</code>, <code>&lt;abbr title&gt;</code>, <code>&lt;q&gt;</code>; 2 ta havola (biri <code>target=&quot;_blank&quot;</code> va <code>rel</code> bilan). Sahifa oxirida <code>&lt;small&gt;</code> bilan muallif yozuvi. <strong>Qo&#39;shimcha (ixtiyoriy):</strong> 2-darsdagi <code>hobbi.html</code> bilan shu sahifa o&#39;rtasida havolalar yarating.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Keyingi dars boshida (takrorlash 10 daqiqada) 1–2 ta ishni ekranda ko&#39;rib chiqing. Xatolarni o&#39;quvchining o&#39;ziga topishga undang.</p>',11))]),t("div",g,[t("h2",m,[i(d,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p>Dasturdagi mezonlarga asoslangan (100 ballik shkala): <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><p>Dasturda joriy nazorat (so&#39;rovlar va bajarilgan ishlar) o&#39;quv jarayoni davomida o&#39;tkaziladi. Quyida har bir dars bo&#39;yicha o&#39;quvchining ishtirokini yozib borish uchun shablon. Ball taqsimoti dasturda alohida berilmagan, shuning uchun quyidagi 100 ball shkalasi taklif etilgan mentor jadvali sifatida (mentor o&#39;zgartirishi mumkin).</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mavzu mohiyatini tushunadi va aytib bera oladi (tezkor nazorat)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri va to&#39;liq bajarilgan</td><td>30</td></tr><tr><td>Kod toza, surilgan, teglar to&#39;g&#39;ri yopilgan</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><p>Qo&#39;shimcha: mustaqil fikrlash va qiyin topshiriqni bajarish — baholashda e&#39;tiborga olinadi (dasturdagi «ijodiy fikrlay oladi» mezoni).</p><h2 id="_1-dars-internet-dns" tabindex="-1">1-dars (Internet, DNS) <a class="header-anchor" href="#_1-dars-internet-dns" aria-label="Permalink to &quot;1-dars (Internet, DNS)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Kod /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>(1-darsda kod kam bo&#39;lgani uchun «Kod» ustuni birinchi HTML fayl va DevTools tahliliga qo&#39;llanadi.)</p><h2 id="_2-dars-html-skelet" tabindex="-1">2-dars (HTML skelet) <a class="header-anchor" href="#_2-dars-html-skelet" aria-label="Permalink to &quot;2-dars (HTML skelet)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Kod /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="_3-dars-matn-teglari-havolalar" tabindex="-1">3-dars (Matn teglari, havolalar) <a class="header-anchor" href="#_3-dars-matn-teglari-havolalar" aria-label="Permalink to &quot;3-dars (Matn teglari, havolalar)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Kod /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="hafta-yakuni" tabindex="-1">Hafta yakuni <a class="header-anchor" href="#hafta-yakuni" aria-label="Permalink to &quot;Hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>1-dars</th><th>2-dars</th><th>3-dars</th><th>O&#39;rtacha</th><th>Baho</th><th>Izoh (kuchli/zaif tomonlari)</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="hafta-xulosasi-va-keyingi-haftaga-ko-prik" tabindex="-1">Hafta xulosasi va keyingi haftaga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-keyingi-haftaga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va keyingi haftaga ko&#39;prik&quot;">​</a></h2><p><strong>Bu hafta:</strong> internetning ishlash tamoyili (DNS, domen, hosting, HTTP/HTTPS), front-end va back-end farqi; HTML hujjat skeleti, <code>head</code>/<code>meta</code>, sarlavhalar, matn teglari, <code>&lt;a&gt;</code> havolasi, block/inline.</p><p><strong>Keyingi hafta (2-hafta, 4–6 darslar):</strong> rasm (<code>&lt;img&gt;</code>), jadval, ro&#39;yxat (<code>ul</code>, <code>ol</code>, <code>li</code>) va forma teglari. Bugungi havola va matn bilan ishlash ko&#39;nikmasi to&#39;g&#39;ridan-to&#39;g&#39;ri kerak bo&#39;ladi: ro&#39;yxatlar menyu yasashda, rasmlar sahifa bezashda, formalar esa ma&#39;lumot yig&#39;ishda ishlatiladi.</p><p>Oraliq yoki yakuniy nazorat bu haftaga to&#39;g&#39;ri kelmaydi (oraliq nazorat chorak oxirida).</p>',18))])])}const _=e(s,[["render",b]]);export{p as __pageData,_ as default};
